/**
 * The Lessons with Kora: what each three-minute lesson teaches. `exams` says who it is for (the app
 * shows a lesson to the regions that sit one of its exams; none means everyone). `brief` is what the
 * script must get right; the writer and the reviewer both see it.
 */
export type Spelling = 'US' | 'UK' | 'WA';

export type Topic = {
  id: string;
  title: string;
  subject: string;
  /** The label on the card: the exam, or the kind of lesson. */
  label: string;
  group: 'cyber' | 'skills' | 'exam' | 'future';
  /** The Future skills subject it belongs to (apps/server/data/skills): the app lists it there beside the YouTube lessons. */
  skill?: 'coding' | 'ui-ux' | 'cybersecurity' | 'ai-prompting' | 'data-science';
  exams: ('sat' | 'gcse' | 'jamb' | 'waec')[];
  spelling: Spelling;
  brief: string;
  /** Whether a real picture or diagram helps this lesson (maths and reading lessons use the board alone). */
  pictures: boolean;
};

